+package testutil
+
+import (
+	"math"
+	"testing"
+)
+
+// InRelTol fails the test unless got is within tol of want, relative to want.
+// For want == 0 the tolerance is absolute.
+func InRelTol(t testing.TB, got, want, tol float64) {
+	t.Helper()
+	if math.IsNaN(got) || math.IsInf(got, 0) {
+		t.Fatalf("got %v, want %v", got, want)
+	}
+	limit := tol * math.Abs(want)
+	if want == 0 {
+		limit = tol
+	}
+	if diff := math.Abs(got - want); diff > limit {
+		t.Fatalf("got %.6f, want %.6f (diff %.6f > %.6f)", got, want, diff, limit)
+	}
+}
