+// volumetricDivisor converts cubic centimetres to chargeable kilograms.
+const volumetricDivisor = 5000.0
+
+// ChargeableKg is the larger of the actual and the volumetric weight.
+func ChargeableKg(p Parcel) float64 {
+	vol := p.LengthCm * p.WidthCm * p.HeightCm / volumetricDivisor
+	return math.Max(p.WeightKg, vol)
