@@ -0,0 +1,41 @@
+'use strict';
+
+class FormatterRegistry {
+  constructor() {
+    this.formatters = new Map();
+    this.middlewares = [];
+    this.fallback = null;
+  }
+
+  register(name, factory, options = {}) {
+    if (this.formatters.has(name) && !options.override) {
+      throw new Error('formatter already registered: ' + name);
+    }
+    this.formatters.set(name, { factory, priority: options.priority ?? 0, tags: options.tags ?? [] });
+    return this;
+  }
+
+  use(middleware) {
+    this.middlewares.push(middleware);
+    return this;
+  }
+
+  setFallback(name) {
+    this.fallback = name;
+    return this;
+  }
+
+  resolve(name, context = {}) {
+    const entry = this.formatters.get(name) ?? this.formatters.get(this.fallback);
+    if (!entry) throw new Error('no formatter: ' + name);
+    const formatter = entry.factory(context);
+    return this.middlewares.reduceRight((next, mw) => (receipt) => mw(receipt, next), formatter);
+  }
+}
+
+const registry = new FormatterRegistry();
+
+registry.register('plain', () => require('./plain').formatPlain);
+registry.setFallback('plain');
+
+module.exports = { FormatterRegistry, registry };
