 export type Currency = 'EUR' | 'USD' | 'GBP' | 'JPY';

+const MINOR_UNITS: Record<Currency, number> = { EUR: 2, USD: 2, GBP: 2, JPY: 0 };
+
 export interface RateTable {
   base: Currency;
   rates: Record<Currency, number>;
 }

-export function convert(amount: number, from: Currency, to: Currency, table: RateTable): number {
-  const inBase = amount / table.rates[from];
-  return inBase * table.rates[to];
+/** Converts an amount in minor units (cents, yen) between currencies, rounding half away from zero. */
+export function convertMinor(minor: number, from: Currency, to: Currency, table: RateTable): number {
+  if (from === to) return minor;
+  const major = minor / 10 ** MINOR_UNITS[from];
+  const converted = (major / table.rates[from]) * table.rates[to];
+  const scaled = converted * 10 ** MINOR_UNITS[to];
+  return Math.sign(scaled) * Math.round(Math.abs(scaled));
+}
+
+export function minorUnits(currency: Currency): number {
+  return MINOR_UNITS[currency];
 }
