+import { isWithinInterval } from 'date-fns';
+
 export interface Discount {
   code: string;
   percentOff: number;
+  validFrom?: Date;
+  validUntil?: Date;
+  minSubtotalCents?: number;
 }

-export function applyDiscount(subtotalCents: number, discount: Discount): number {
-  const off = Math.round((subtotalCents * discount.percentOff) / 100);
-  return subtotalCents - off;
+export function isApplicable(discount: Discount, subtotalCents: number, at: Date): boolean {
+  if (discount.minSubtotalCents !== undefined && subtotalCents < discount.minSubtotalCents) {
+    return false;
+  }
+  if (discount.validFrom && discount.validUntil) {
+    return isWithinInterval(at, { start: discount.validFrom, end: discount.validUntil });
+  }
+  if (discount.validFrom) return at >= discount.validFrom;
+  if (discount.validUntil) return at <= discount.validUntil;
+  return true;
+}
+
+export function applyDiscount(subtotalCents: number, discount: Discount, at: Date = new Date()): number {
+  if (!isApplicable(discount, subtotalCents, at)) return subtotalCents;
+  const off = Math.floor((subtotalCents * discount.percentOff) / 100);
+  return Math.max(0, subtotalCents - off);
 }
