+import { applyDiscount, isApplicable, Discount } from './discounts';
+
+const spring: Discount = {
+  code: 'SPRING',
+  percentOff: 15,
+  validFrom: new Date('2026-03-01T00:00:00Z'),
+  validUntil: new Date('2026-03-31T23:59:59Z'),
+};
+
+describe('isApplicable', () => {
+  it('is true inside the validity window', () => {
+    expect(isApplicable(spring, 5000, new Date('2026-03-15T12:00:00Z'))).toBe(true);
+  });
+
+  it('is false after the window closes', () => {
+    expect(isApplicable(spring, 5000, new Date('2026-04-01T00:00:00Z'))).toBe(false);
+  });
+
+  it('is false below the minimum subtotal', () => {
+    const d = { ...spring, minSubtotalCents: 3000 };
+    expect(isApplicable(d, 2999, new Date('2026-03-15T12:00:00Z'))).toBe(false);
+  });
+
+  it('honours an open-ended start date', () => {
+    const d: Discount = { code: 'NEW', percentOff: 10, validFrom: new Date('2026-01-01T00:00:00Z') };
+    expect(isApplicable(d, 100, new Date('2025-12-31T23:59:59Z'))).toBe(false);
+    expect(isApplicable(d, 100, new Date('2026-01-01T00:00:00Z'))).toBe(true);
+  });
+});
+
+describe('applyDiscount', () => {
+  const at = new Date('2026-03-15T12:00:00Z');
+
+  it('rounds the discount down to whole cents', () => {
+    // 15% of 999 is 149.85, so 149 off
+    expect(applyDiscount(999, spring, at)).toBe(850);
+  });
+
+  it('leaves the subtotal alone when the code does not apply', () => {
+    expect(applyDiscount(999, spring, new Date('2026-05-01T00:00:00Z'))).toBe(999);
+  });
+
+  it('never goes below zero', () => {
+    expect(applyDiscount(500, { code: 'ALL', percentOff: 120 }, at)).toBe(0);
+  });
+});
