+package ratelimit
+
+import (
+	"testing"
+	"time"
+)
+
+type fakeClock struct{ t time.Time }
+
+func (c *fakeClock) Now() time.Time         { return c.t }
+func (c *fakeClock) Advance(d time.Duration) { c.t = c.t.Add(d) }
+
+func TestHitExactlyOneWindowAgoIsEvicted(t *testing.T) {
+	clk := &fakeClock{t: time.Unix(1_700_000_000, 0)}
+	w := NewSlidingWindow(1, time.Second, clk.Now)
+
+	if !w.Allow() {
+		t.Fatal("first request should be allowed")
+	}
+	clk.Advance(time.Second)
+	if !w.Allow() {
+		t.Fatal("request exactly one window later should be allowed")
+	}
+}
+
+func TestHitJustInsideWindowStillCounts(t *testing.T) {
+	clk := &fakeClock{t: time.Unix(1_700_000_000, 0)}
+	w := NewSlidingWindow(1, time.Second, clk.Now)
+
+	w.Allow()
+	clk.Advance(time.Second - time.Nanosecond)
+	if w.Allow() {
+		t.Fatal("request inside the window should be refused")
+	}
+}
+
+func TestEvictKeepsOrder(t *testing.T) {
+	clk := &fakeClock{t: time.Unix(1_700_000_000, 0)}
+	w := NewSlidingWindow(3, 10*time.Second, clk.Now)
+
+	for i := 0; i < 3; i++ {
+		w.Allow()
+		clk.Advance(4 * time.Second)
+	}
+	// hits at 0s, 4s, 8s; now is 12s, so 0s is out and 4s, 8s remain
+	if !w.Allow() {
+		t.Fatal("one slot should have freed up")
+	}
+	if got := len(w.hits); got != 3 {
+		t.Fatalf("hits = %d, want 3", got)
+	}
+}
