+package testutil
+
+import (
+	"math"
+	"testing"
+)
+
+// InCents fails the test unless got and want round to the same number of cents.
+func InCents(t testing.TB, got, want float64) {
+	t.Helper()
+	if math.IsNaN(got) || math.IsInf(got, 0) {
+		t.Fatalf("got %v, want %.2f", got, want)
+	}
+	if math.Round(got*100) != math.Round(want*100) {
+		t.Fatalf("got %.4f, want %.2f", got, want)
+	}
+}
